{
  "name": "Conversational German",
  "goals": [
    {
      "title": "Greet someone at a Munich dinner",
      "description": "Place your starting level while learning warm, natural greetings and the du/Sie distinction that shapes every German interaction.",
      "concepts": [
        { "label": "Du vs Sie", "kind": "concept" },
        { "label": "Common greeting phrases", "kind": "concept" },
        { "label": "Introducing yourself aloud", "kind": "skill" }
      ]
    },
    {
      "title": "Ask simple questions naturally",
      "description": "Build the word-order patterns behind everyday German questions, then practice asking and answering them out loud.",
      "concepts": [
        { "label": "Question word order", "kind": "concept" },
        { "label": "W-question words", "kind": "concept" },
        { "label": "Asking and answering aloud", "kind": "skill" }
      ]
    },
    {
      "title": "Introduce your family",
      "description": "Talk about who's who at the table — parents, siblings, partners — using possessives and simple descriptions.",
      "concepts": [
        { "label": "Family vocabulary", "kind": "concept" },
        { "label": "Possessive pronouns", "kind": "concept" },
        { "label": "Describing relationships aloud", "kind": "skill" }
      ]
    },
    {
      "title": "Talk about food you like and dislike",
      "description": "Order, comment on, and react to food naturally, expressing likes and dislikes beyond just 'gut'.",
      "concepts": [
        { "label": "Food vocabulary", "kind": "concept" },
        { "label": "Gern vs nicht gern", "kind": "concept" },
        { "label": "Reacting to dishes aloud", "kind": "skill" }
      ]
    },
    {
      "title": "Share opinions politely",
      "description": "Give a soft opinion at the table without sounding blunt or textbook-stiff, using hedges and polite framing.",
      "concepts": [
        { "label": "Opinion-giving phrases", "kind": "concept" },
        { "label": "Polite hedging", "kind": "concept" },
        { "label": "Disagreeing gently", "kind": "skill" }
      ]
    },
    {
      "title": "Make small talk at the table",
      "description": "Fill natural pauses with weather, compliments, and easy follow-up questions that keep dinner conversation going.",
      "concepts": [
        { "label": "Small talk openers", "kind": "concept" },
        { "label": "Follow-up questions", "kind": "skill" },
        { "label": "Weather and compliments", "kind": "concept" }
      ]
    },
    {
      "title": "Use everyday Bavarian touches",
      "description": "Recognize a few common Bavarian expressions and table customs so Munich dinners feel familiar, not foreign.",
      "concepts": [
        { "label": "Bavarian greetings", "kind": "concept" },
        { "label": "Munich table customs", "kind": "concept" },
        { "label": "Recognizing dialect flavor", "kind": "skill" }
      ]
    }
  ]
}
